export { default as ModelViewer } from './ModelViewer.vue';
export type {
  ModelViewerEnvironment,
  ModelViewerExpose,
  ModelViewerIntro,
  ModelViewerProps,
} from './types';

import {
  Box3,
  EquirectangularReflectionMapping,
  Mesh,
  Texture,
  TextureLoader,
  Vector3,
} from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { GLTFParser } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader.js';
import { HDRLoader } from 'three/examples/jsm/loaders/HDRLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import type { DataTexture, Material, Object3D } from 'three';
import type { ModelBounds, ModelViewerEnvironment } from './types';

const HDRI_BASE =
  'https://cdn.jsdelivr.net/gh/pmndrs/drei-assets@456060a26bbeb8fdf79326f224b6d99b8bcce736/hdri/';
const DRACO_DECODERS =
  'https://www.gstatic.com/draco/versioned/decoders/1.5.5/';

const ENVIRONMENT_FILES: Record<
  Exclude<ModelViewerEnvironment, 'none'>,
  string
> = {
  apartment: 'lebombo_1k.hdr',
  city: 'potsdamer_platz_1k.hdr',
  dawn: 'kiara_1_dawn_1k.hdr',
  forest: 'forest_slope_1k.hdr',
  lobby: 'st_fagans_interior_1k.hdr',
  night: 'dikhololo_night_1k.hdr',
  park: 'rooitou_park_1k.hdr',
  studio: 'studio_small_03_1k.hdr',
  sunset: 'venice_sunset_1k.hdr',
  warehouse: 'empty_warehouse_01_1k.hdr',
};

/** Loads a studio HDRI preset as an equirectangular environment map. */
export function loadEnvironment(
  environment: Exclude<ModelViewerEnvironment, 'none'>,
): Promise<DataTexture> {
  return new HDRLoader()
    .loadAsync(HDRI_BASE + ENVIRONMENT_FILES[environment])
    .then((texture) => {
      texture.mapping = EquirectangularReflectionMapping;
      return texture;
    });
}

/**
 * Decode embedded glTF images through <img> instead of fetch(): blob: image
 * URLs are allowed by far more CSPs under img-src than under connect-src.
 */
function imageElementTextures(parser: GLTFParser) {
  parser.textureLoader = new TextureLoader(parser.options.manager);
  parser.textureLoader.setCrossOrigin(parser.options.crossOrigin);
  return { name: 'NXUI_image_element_textures' };
}

/** Loads a glb/gltf (Draco + Meshopt aware), fbx or obj model. */
export async function loadModel(url: string): Promise<Object3D> {
  const extension = (url.split('?')[0] ?? '').split('.').pop()?.toLowerCase();
  if (extension === 'fbx') return new FBXLoader().loadAsync(url);
  if (extension === 'obj') return new OBJLoader().loadAsync(url);
  const draco = new DRACOLoader().setDecoderPath(DRACO_DECODERS);
  const loader = new GLTFLoader()
    .setDRACOLoader(draco)
    .setMeshoptDecoder(MeshoptDecoder)
    .register(imageElementTextures);
  try {
    const gltf = await loader.loadAsync(url);
    return gltf.scene;
  } finally {
    draco.dispose();
  }
}

/** Unit-fit bounds: scale so the longest side is 2, plus radius and floor. */
export function measureModel(object: Object3D): ModelBounds {
  const box = new Box3().setFromObject(object);
  const extent = box.getSize(new Vector3());
  const center = box.getCenter(new Vector3());
  const scale = 2 / Math.max(extent.x, extent.y, extent.z, 0.0001);
  return {
    scale,
    center,
    radius: (extent.length() / 2) * scale,
    floor: (extent.y / 2) * scale,
  };
}

function disposeMaterial(material: Material) {
  for (const value of Object.values(material)) {
    if (value instanceof Texture) value.dispose();
  }
  material.dispose();
}

/** Frees every geometry, material and texture under `object`. */
export function disposeModel(object: Object3D) {
  object.traverse((child) => {
    if (!(child instanceof Mesh)) return;
    child.geometry.dispose();
    const materials: Material[] = Array.isArray(child.material)
      ? child.material
      : [child.material];
    materials.forEach(disposeMaterial);
  });
}

import {
  Color,
  Group,
  Mesh,
  MeshBasicMaterial,
  MeshDepthMaterial,
  OrthographicCamera,
  PlaneGeometry,
  ShaderMaterial,
  WebGLRenderTarget,
} from 'three';
import { HorizontalBlurShader } from 'three/examples/jsm/shaders/HorizontalBlurShader.js';
import { VerticalBlurShader } from 'three/examples/jsm/shaders/VerticalBlurShader.js';
import type { Scene, WebGLRenderer } from 'three';
import type { ContactShadowOptions, ContactShadows } from './types';

/**
 * Soft contact shadow: renders the scene's depth from below into a render
 * target, blurs it twice and maps it onto a floor plane.
 */
export function createContactShadows(): ContactShadows {
  const resolution = 512;
  const group = new Group();
  group.rotation.x = Math.PI / 2;

  const renderTarget = new WebGLRenderTarget(resolution, resolution);
  const renderTargetBlur = new WebGLRenderTarget(resolution, resolution);
  renderTarget.texture.generateMipmaps = false;
  renderTargetBlur.texture.generateMipmaps = false;

  const planeGeometry = new PlaneGeometry(1, 1).rotateX(Math.PI / 2);
  const blurGeometry = new PlaneGeometry(1, 1);
  const blurPlane = new Mesh(blurGeometry);
  const blurCamera = new OrthographicCamera(-0.5, 0.5, 0.5, -0.5, 0, 2);
  blurCamera.position.set(0, 0, 1);
  blurCamera.updateMatrixWorld();
  const shadowMaterial = new MeshBasicMaterial({
    map: renderTarget.texture,
    transparent: true,
    depthWrite: false,
  });
  const plane = new Mesh(planeGeometry, shadowMaterial);
  plane.scale.set(1, -1, 1);
  plane.rotation.set(-Math.PI / 2, 0, 0);
  group.add(plane);

  const camera = new OrthographicCamera(-0.5, 0.5, 0.5, -0.5, 0, 1);
  group.add(camera);

  const shadowColor = { value: new Color('#000000') };
  const depthMaterial = new MeshDepthMaterial();
  depthMaterial.depthTest = false;
  depthMaterial.depthWrite = false;
  depthMaterial.onBeforeCompile = (shader) => {
    shader.uniforms.ucolor = shadowColor;
    shader.fragmentShader = shader.fragmentShader
      .replace('void main() {', 'uniform vec3 ucolor;\nvoid main() {')
      .replace(
        'vec4( vec3( 1.0 - fragCoordZ ), opacity );',
        'vec4( ucolor * fragCoordZ * 2.0, ( 1.0 - fragCoordZ ) * 1.0 );',
      );
  };

  const horizontalBlur = new ShaderMaterial(HorizontalBlurShader);
  const verticalBlur = new ShaderMaterial(VerticalBlurShader);
  horizontalBlur.depthTest = false;
  verticalBlur.depthTest = false;

  let size = 1;
  let far = 1;

  function blurShadows(renderer: WebGLRenderer, blur: number) {
    blurPlane.visible = true;
    blurPlane.material = horizontalBlur;
    horizontalBlur.uniforms.tDiffuse!.value = renderTarget.texture;
    horizontalBlur.uniforms.h!.value = blur / 256;
    renderer.setRenderTarget(renderTargetBlur);
    renderer.render(blurPlane, blurCamera);
    blurPlane.material = verticalBlur;
    verticalBlur.uniforms.tDiffuse!.value = renderTargetBlur.texture;
    verticalBlur.uniforms.v!.value = blur / 256;
    renderer.setRenderTarget(renderTarget);
    renderer.render(blurPlane, blurCamera);
    blurPlane.visible = false;
  }

  function configure(options: ContactShadowOptions) {
    group.position.set(0, options.y, 0);
    shadowMaterial.opacity = options.opacity;
    if (options.scale !== size || options.far !== far) {
      size = options.scale;
      far = options.far;
      plane.scale.set(size, -1, size);
      camera.left = -size / 2;
      camera.right = size / 2;
      camera.top = size / 2;
      camera.bottom = -size / 2;
      camera.far = far;
      camera.updateProjectionMatrix();
    }
  }

  function render(renderer: WebGLRenderer, scene: Scene, blur: number) {
    if (!group.visible) return;
    const background = scene.background;
    const override = scene.overrideMaterial;
    const previousTarget = renderer.getRenderTarget();
    scene.background = null;
    scene.overrideMaterial = depthMaterial;
    plane.visible = false;
    renderer.setRenderTarget(renderTarget);
    renderer.clear();
    renderer.render(scene, camera);
    blurShadows(renderer, blur);
    blurShadows(renderer, blur * 0.4);
    renderer.setRenderTarget(previousTarget);
    plane.visible = true;
    scene.overrideMaterial = override;
    scene.background = background;
  }

  function dispose() {
    renderTarget.dispose();
    renderTargetBlur.dispose();
    planeGeometry.dispose();
    blurGeometry.dispose();
    shadowMaterial.dispose();
    depthMaterial.dispose();
    horizontalBlur.dispose();
    verticalBlur.dispose();
  }

  return { group, configure, render, dispose };
}

import type { Group, Scene, Vector3, WebGLRenderer } from 'three';

export type ModelViewerEnvironment =
  | 'studio'
  | 'city'
  | 'sunset'
  | 'dawn'
  | 'warehouse'
  | 'apartment'
  | 'lobby'
  | 'night'
  | 'park'
  | 'forest'
  | 'none';

export type ModelViewerIntro = 'rise' | 'spin' | 'fade' | 'none';

export interface ModelViewerProps {
  url?: string;
  width?: number | string;
  height?: number | string;
  environment?: ModelViewerEnvironment;
  environmentIntensity?: number;
  exposure?: number;
  autoRotate?: boolean;
  autoRotateSpeed?: number;
  autoRotateDelay?: number;
  dragRotate?: boolean;
  turntable?: boolean;
  zoom?: boolean;
  minZoom?: number;
  maxZoom?: number;
  hoverTilt?: number;
  float?: number;
  shadow?: boolean;
  shadowOpacity?: number;
  intro?: ModelViewerIntro;
  startAngle?: number;
  tilt?: number;
  offsetX?: number;
  offsetY?: number;
  fit?: number;
  resetOnDoubleClick?: boolean;
  class?: string;
}

export interface ModelViewerExpose {
  /** Returns the current frame as an image data URL. */
  capture: (type?: string) => string | null;
}

export interface ModelBounds {
  scale: number;
  center: Vector3;
  radius: number;
  floor: number;
}

export interface ModelMotion {
  yaw: number;
  pitch: number;
  yawVelocity: number;
  pitchVelocity: number;
  zoom: number;
  zoomGoal: number;
  tiltX: number;
  tiltY: number;
  tiltGoalX: number;
  tiltGoalY: number;
  spinSpeed: number;
  idle: number;
  dragging: boolean;
  intro: number;
  clock: number;
  reset: { yaw: number; pitch: number } | null;
}

export interface ModelPointer {
  x: number;
  y: number;
  t: number;
}

export interface ContactShadowOptions {
  y: number;
  opacity: number;
  scale: number;
  far: number;
}

export interface ContactShadows {
  group: Group;
  configure: (options: ContactShadowOptions) => void;
  render: (renderer: WebGLRenderer, scene: Scene, blur: number) => void;
  dispose: () => void;
}
